# -*- coding: utf-8 -*-
import time
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes


class Timeout(LibraryError):
    def __init__(self):
        super(Timeout, self).__init__(exception_causes.TIMEOUT, '')


class Timer(object):
    def __init__(self):
        self._start_time = None
        self._timeout = 0

    def start(self, timeout):
        self._start_time = time.time()
        self._timeout = timeout

    def is_started(self):
        return self._start_time is not None

    def is_timeout(self):
        return self.is_started() and self.remaining_time <= 0

    def raise_if_timeout(self):
        if self.is_timeout():
            raise Timeout()

    @property
    def remaining_time(self):
        elapsed_time = time.time() - self._start_time
        return max(0, self._timeout - elapsed_time)
